  insert into public.learning_progress(user_id,lesson_id) values(p_actor,lesson_uuid) on conflict do nothing;
   insert into public.learning_attempts(user_id,section_id,snapshot) values(p_actor,section_uuid,snapshot_json) returning * into a;
   insert into public.audit_log(actor_id,action,target) values(p_actor,'learning.submitted',a.id::text);
  insert into public.learning_grants(id,user_id,section_id,granted_by) values(request_uuid,target_user,section_uuid,p_actor);
  insert into public.audit_log(actor_id,action,target) values(p_actor,'learning.granted',target_user::text||':'||section_uuid::text);
  insert into public.audit_log(actor_id,action,target) values(p_actor,'learning.edited',lesson_uuid::text);
insert into public.learning_sections(id,slug,title,description,sort_order) values
('c5842671-76e6-5bcc-a891-8212048ff716','basics','Основы покера','База для уверенной работы за столом.',0),
('fcbf4569-a578-5369-9de1-9a35fae62ca6','combinations','Комбинации','Старшинство рук и определение победителя.',1),
('6e22cc37-5558-5f3d-a4d3-352a7e67a32d','deal','Схема раздачи','Порядок действий дилера от подготовки до следующей раздачи.',2),
('4e83d351-53fa-5b90-a93b-b5ae42e43e72','disputes','Спорные моменты','Разбор ситуаций из исходных материалов клуба.',3) on conflict do nothing;
insert into public.learning_lessons(id,section_id,title,theory,sort_order,cards,steps,video_url) values
('d359ae97-98a8-5181-ada2-cbff12c4026e','c5842671-76e6-5bcc-a891-8212048ff716','Цель игры','В безлимитном Техасском холдеме игрок старается забрать банк. Для этого нужно собрать лучшую комбинацию из пяти карт или заставить всех соперников сбросить карты.',0,'[]'::jsonb,'[]'::jsonb,null),
('985e86af-b9ea-5dc4-84ed-d257c2c9c026','c5842671-76e6-5bcc-a891-8212048ff716','Баттон и блайнды','Баттон (дилерский жетон) определяет последнюю позицию за столом и перемещается по часовой стрелке после каждой раздачи. После баттона находятся малый и большой блайнды.',1,'[]'::jsonb,'[]'::jsonb,null),
('801b7ab1-bb16-51c1-80fc-ba9d323318e6','c5842671-76e6-5bcc-a891-8212048ff716','Анте','В нашей игре анте берётся с большого блайнда до раздачи карт в размере одного большого блайнда. Сначала определяется позиция BB и анте, затем анте забирается в банк.',2,'[]'::jsonb,'[]'::jsonb,null),
('1fea0586-b336-5359-9229-fcfd8c5c6372','c5842671-76e6-5bcc-a891-8212048ff716','Префлоп','Префлоп — первый раунд торгов до выхода общих карт. После блайндов и анте дилер раздаёт по две карманные карты. Первое слово у игрока после большого блайнда.',3,'[]'::jsonb,'[]'::jsonb,null),
('6999b116-50b6-576b-a49f-1889e6abbc77','c5842671-76e6-5bcc-a891-8212048ff716','Флоп','Флоп — первые три общие карты. После уравнивания ставок дилер забирает фишки в банк, делает стук, сжигает карту и открывает флоп. Торги начинаются с малого блайнда.',4,'[]'::jsonb,'[]'::jsonb,null),
('3392551a-cef7-5b30-9dfa-ddc5818f8c40','c5842671-76e6-5bcc-a891-8212048ff716','Тёрн','Тёрн — четвёртая общая карта. После завершения торгов на флопе дилер забирает фишки в банк, делает стук, сжигает карту, открывает тёрн и запускает следующий круг торгов.',5,'[]'::jsonb,'[]'::jsonb,null),
('9dd56685-bc85-56c0-9f21-27b0f2467033','c5842671-76e6-5bcc-a891-8212048ff716','Ривер','Ривер — пятая общая карта. После торгов на тёрне дилер сжигает карту, открывает ривер, проводит последний круг торгов и переходит к шоудауну.',6,'[]'::jsonb,'[]'::jsonb,null),
('3bd55e8e-589a-54e4-82f6-8443665831d2','c5842671-76e6-5bcc-a891-8212048ff716','Действия игрока','Чек — пропустить ход без ставки. Бет — поставить. Колл — уравнять ставку. Рейз — увеличить ставку. Фолд — сбросить карты и выйти из раздачи.',7,'[]'::jsonb,'[]'::jsonb,null),
('f7028b20-b7cb-5aa2-9ef9-d8652536f075','c5842671-76e6-5bcc-a891-8212048ff716','Вскрытие','На шоудауне игроки открывают карты, если лидера нельзя определить без вскрытия. Если никто не открывает первым, слово идёт от первого игрока после баттона по часовой стрелке. Увидев старшую руку, игрок может сбросить карты закрытыми.',8,'[]'::jsonb,'[]'::jsonb,null),
('f3f07447-b14e-5a22-97ba-725379838975','c5842671-76e6-5bcc-a891-8212048ff716','Основной и сайд-поты','Игрок в олл-ине больше не участвует в торгах и претендует только на банки, в которые вложился. Основной банк и сайд-поты формируются по уровням вкладов; в сайд-поте участвуют только внесшие в него фишки.',9,'[]'::jsonb,'[]'::jsonb,null),
('b9d20354-0046-50e1-9c9b-29d48e7cb80a','c5842671-76e6-5bcc-a891-8212048ff716','Видимые фишки и карты','Стек игрока должен быть виден, и любой игрок может спросить его размер. Нельзя отходить от стола с картами или показывать карты другим игрокам. Открытая рука до шоудауна считается мёртвой, кроме хедз-апа.',10,'[]'::jsonb,'[]'::jsonb,null),
('97d327df-a82a-5afb-b5c9-d21e2134f995','c5842671-76e6-5bcc-a891-8212048ff716','Олл-ин и короткий стек','Олл-ин — ставка всех оставшихся фишек. Игрок после олл-ина больше не участвует в торгах и претендует только на банки, в которые вложился. Если стек меньше большого блайнда, игрок идёт в олл-ин, а остальные коллируют BB.',11,'[]'::jsonb,'[]'::jsonb,null),
('9962be16-b3f4-571b-8efd-e4ab6bc62198','c5842671-76e6-5bcc-a891-8212048ff716','Хедз-ап','Хедз-ап — игра между двумя оставшимися игроками. Баттон разыгрывается заново: на баттоне находится малый блайнд, раздача начинается с большого блайнда, а первым действует малый блайнд.',12,'[]'::jsonb,'[]'::jsonb,null),
('855a9021-01ea-5849-90e2-cf8aa83ac7a7','c5842671-76e6-5bcc-a891-8212048ff716','Мёртвый баттон','Мёртвый баттон находится на месте выбывшего игрока. Это пустой бокс: карты этому месту не раздаются, а позиции блайндов определяются по правилам стола.',13,'[]'::jsonb,'[]'::jsonb,null),
('85117c7f-18a7-51a1-92e2-0b72b9135da2','c5842671-76e6-5bcc-a891-8212048ff716','Повышение блайндов','При сигнале о повышении во время незавершённой раздачи игра заканчивается на старых блайндах, а следующая раздача идёт по новым. Если первая карта уже у игрока, остаются старые блайнды; до выдачи первой карты действуют новые.',14,'[]'::jsonb,'[]'::jsonb,null),
('fefc087f-26d3-5082-9968-674706eb5e26','fcbf4569-a578-5369-9de1-9a35fae62ca6','Старшая карта','Если ни у кого нет другой комбинации, побеждает самая старшая карта. При совпадении сравниваются следующие карты — кикеры.',0,'["A__hearts.png", "10_spades.png", "8_clubs.png", "5_diamonds.png", "2_hearts.png"]'::jsonb,'[]'::jsonb,null),
('84bb00e1-ad8f-5dc2-97b1-7d12c949f471','fcbf4569-a578-5369-9de1-9a35fae62ca6','Пара','Пара — это две карты одного достоинства. Сначала сравнивается достоинство пары, затем кикеры.',1,'["K_hearts.png", "K_spades.png", "9_clubs.png", "6_diamonds.png", "2_hearts.png"]'::jsonb,'[]'::jsonb,null),
('ab59786e-2c96-5021-8c71-7b16c9b5ec3d','fcbf4569-a578-5369-9de1-9a35fae62ca6','Две пары','Две пары — две разные пары карт одного достоинства. Сначала сравнивается старшая пара, затем младшая и кикер.',2,'["Q_hearts.png", "Q_spades.png", "7_clubs.png", "7_diamonds.png", "A_spades.png"]'::jsonb,'[]'::jsonb,null),
('3d8a0198-9312-5485-b00c-64073c901083','fcbf4569-a578-5369-9de1-9a35fae62ca6','Тройка','Тройка — три карты одного достоинства. В покере её также называют сетом или трипсом в зависимости от ситуации.',3,'["8_hearts.png", "8_spades.png", "8_clubs.png", "K_diamonds.png", "3_hearts.png"]'::jsonb,'[]'::jsonb,null),
('2f9568a9-28f4-54a1-8a82-9cf4f8ed218e','fcbf4569-a578-5369-9de1-9a35fae62ca6','Стрит','Стрит — пять карт подряд по достоинству. Масти карт могут быть разными. Туз может быть младшей картой в комбинации A-2-3-4-5.',4,'["5_hearts.png", "6_spades.png", "7_clubs.png", "8_diamonds.png", "9_hearts.png"]'::jsonb,'[]'::jsonb,null),
('143da47a-f903-59b1-ae2c-b9cbf8a18e77','fcbf4569-a578-5369-9de1-9a35fae62ca6','Флеш','Флеш — пять карт одной масти. Достоинства карт не обязаны идти подряд.',5,'["A__hearts.png", "J_hearts.png", "8_hearts.png", "5_hearts.png", "2_hearts.png"]'::jsonb,'[]'::jsonb,null),
('6870a2f9-8fc9-5cfe-a29e-904f361a6f03','fcbf4569-a578-5369-9de1-9a35fae62ca6','Фулл-хаус','Фулл-хаус состоит из тройки и пары. Сначала сравнивается тройка, затем пара.',6,'["10_hearts.png", "10_spades.png", "10_clubs.png", "4_diamonds.png", "4_hearts.png"]'::jsonb,'[]'::jsonb,null),
('82ab8b91-ffac-5505-a901-676a2b136894','fcbf4569-a578-5369-9de1-9a35fae62ca6','Каре','Каре — четыре карты одного достоинства. Пятая карта называется кикером и учитывается, если это необходимо.',7,'["9_hearts.png", "9_spades.png", "9_clubs.png", "9_diamonds.png", "A_spades.png"]'::jsonb,'[]'::jsonb,null),
('bcaba417-fdba-563a-a8f1-5f74480674de','fcbf4569-a578-5369-9de1-9a35fae62ca6','Стрит-флеш','Стрит-флеш — пять последовательных карт одной масти. Это сильнее каре.',8,'["5_spades.png", "6_spades.png", "7_spades.png", "8_spades.png", "9_spades.png"]'::jsonb,'[]'::jsonb,null),
('1cc8266f-ec42-5f79-b570-0127b58cbde0','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Подготовка колоды','Дилер приходит с готовой колодой. При смене дилера он проверяет наличие 52 целых карт, выполняет шеми-шафл, три врезки, срезку и проверяет позиции малого и большого блайндов.',0,'[]'::jsonb,'[]'::jsonb,null),
('97c88000-14d3-5202-98fc-c0ab6ec12e22','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Spread перед началом','Spread — показ всей готовой колоды лицом вверх перед собой. Он нужен, чтобы убедиться, что на месте все 52 карты, нет дублей, разных рубашек и повреждённых карт.',1,'[]'::jsonb,'[]'::jsonb,null),
('b640ced2-a490-5d2b-badb-6ad6f4e746d4','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Розыгрыш баттона','В начале турнира после spread, шеми-шафла, 2-1-1 и срезки дилер разыгрывает баттон: открывает по одной карте на каждого игрока. Баттон получает игрок с самой старшей картой; при равном достоинстве учитывается старшинство мастей. При смене дилера баттон не разыгрывается заново.',2,'[]'::jsonb,'[]'::jsonb,null),
('01c6289a-1987-55f6-8fff-5bc68110e0bb','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Перетасовка 2-1-1','Схема 2-1-1 — два рифла, стрип и ещё один рифл. В начале турнира после неё выполняется срезка и розыгрыш баттона. После каждой раздачи колода снова перемешивается 2-1-1 и срезается.',3,'[]'::jsonb,'[]'::jsonb,null),
('35b56ec8-4b85-50fd-8932-6463948ea647','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Раздача карманных карт','После определения MB, BB и анте дилер забирает анте и раздаёт карманные карты по часовой стрелке, начиная с малого блайнда: один круг, затем второй. При вскрытии одной карты её объявляют и заменяют после завершения раздачи карманных карт по процедуре рума.',4,'[]'::jsonb,'[]'::jsonb,null),
('8e10dd48-279c-5e8e-b3b9-ec9b3f058ee6','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Общие карты','После каждого завершённого круга торгов дилер забирает ставки в банк и делает стук. Затем сжигает карту и выкладывает флоп из трёх карт, тёрн и ривер — по одной карте.',5,'[]'::jsonb,'[]'::jsonb,null),
('d80577fe-db6a-557f-ba18-fb600be0bac0','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','После раздачи','После шоудауна дилер разбирает сайд-поты, вручает выигрыш, собирает карты и передвигает баттон. Перед следующей раздачей выполняется 2-1-1 и срезка.',6,'[]'::jsonb,'[]'::jsonb,null),
('85344f3e-dfea-5664-810f-71b809529720','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Полная схема раздачи','Полный порядок работы дилера: начало турнира включает розыгрыш баттона; при смене дилера выполняются проверка колоды, шеми-шафл, три врезки, срезка и проверка блайндов. После каждой раздачи баттон передвигается.',7,'[]'::jsonb,'["Spread всей колоды", "Шеми-шафл", "2-1-1 и срезка", "Розыгрыш баттона", "Определение MB, BB и анте", "Забрать анте", "Раздать руки по 2 карты", "Торги на префлопе", "Флоп, тёрн и ривер с сжиганием", "Шоудаун", "Разобрать сайд-поты", "Вручить выигрыш", "Собрать карты", "Передвинуть баттон"]'::jsonb,null),
('9387d05b-362a-5269-9a00-e4222bf99779','6e22cc37-5558-5f3d-a4d3-352a7e67a32d','Собери схему раздачи','Перетащи этапы начала турнира в правильном порядке — от spread до сбора карт и перемещения баттона.',8,'[]'::jsonb,'["Spread всей колоды", "Шеми-шафл", "2-1-1 и срезка", "Розыгрыш баттона", "Определение MB, BB и анте", "Забрать анте", "Раздать руки по 2 карты", "Торги на префлопе", "Флоп, тёрн и ривер с сжиганием", "Шоудаун", "Разобрать сайд-поты", "Вручить выигрыш", "Собрать карты", "Передвинуть баттон"]'::jsonb,null),
('dc320b28-9fd9-578b-806d-8d266a767725','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Преждевременно открытый флоп','Если флоп открыт преждевременно и активных действий до него не было, карты замешиваются обратно и флоп выкладывается заново. При ошибках на флопе, тёрне или ривере карты не срезаются.',0,'[]'::jsonb,'[]'::jsonb,null),
('082c1b2b-8b68-5120-8b23-d99f7d4a625e','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Четыре карты на флопе','Если на флопе открыли четыре карты вместо трёх, весь флоп убирается, замешивается обратно и выкладывается заново.',1,'[]'::jsonb,'[]'::jsonb,null),
('676d7a2a-2ba1-55c9-a59d-1e73b858b890','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Не сожгли карту перед флопом','Если карта перед флопом не была сожжена и активных действий нет, карты берутся обратно, выполняется шафл три раза без срезки, затем сжигается карта и выкладывается флоп.',2,'[]'::jsonb,'[]'::jsonb,null),
('1a7ace09-7150-5454-a7fb-950ef84ac0da','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Преждевременно открытый тёрн','Если тёрн открыт раньше времени и активных действий до него не было, карту возвращают в колоду, замешивают и выкладывают тёрн заново без срезки.',3,'[]'::jsonb,'[]'::jsonb,null),
('fc3dbd36-359c-56fa-be69-018c4630f68f','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Преждевременно открытый ривер','Если ривер открыт раньше времени и активных действий до него не было, карту возвращают в колоду, замешивают и выкладывают ривер заново без срезки.',4,'[]'::jsonb,'[]'::jsonb,null),
('508561c4-9928-58af-af48-52b2622064a4','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Вскрытая карта после большого блайнда','Если после большого блайнда вскрылась одна или несколько карт, их показывают столу и кладут рубашкой вниз в сжигание. Пропущенный бокс продолжают раздавать по часовой стрелке, а засвеченную карту используют для флопа.',5,'[]'::jsonb,'[]'::jsonb,null),
('a9a68173-066d-5e6c-96a4-8a827a8c9ea2','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Основания для перераздачи','Перераздача проводится, если до большого блайнда вскрылась карта, при раздаче вскрылись любые две карты, пропустили игрока с фишками, в колоде меньше 52 карт, обнаружен дубль, разные рубашки или карта не целая.',6,'[]'::jsonb,'[]'::jsonb,null),
('3600c102-4075-5e81-91b6-78c860e5f627','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Преждевременная выкладка карты','Если дилер преждевременно открыл карту на любой улице, он останавливает действие и сообщает об ошибке. Дальнейшее решение принимается по правилам соответствующей улицы.',7,'[]'::jsonb,'[]'::jsonb,null),
('625a88b0-ca7d-52cf-a9b8-3d990049e38c','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Забыли срезать колоду','Если после перемешивания дилер забыл выполнить срезку колоды, он останавливает процедуру и исправляет ошибку по правилам рума до продолжения раздачи.',8,'[]'::jsonb,'[]'::jsonb,null),
('6dbf5e2a-b4b8-5867-b43c-acf0a901a259','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Недоданная карта','Если дилер пропустил игрока и не выдал карту, раздачу нужно остановить и применить установленную процедуру исправления. Нельзя молча продолжать раздачу.',9,'[]'::jsonb,'[]'::jsonb,null),
('8fdab1b4-6b41-58e0-8010-8ad78eff2a7c','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Открытые карманные карты','Если при раздаче карманных карт карта игрока открылась, дилер останавливает действие и применяет процедуру для открытой карты. Нельзя самостоятельно решать, кому оставить карту.',10,'[]'::jsonb,'[]'::jsonb,null),
('a79bd8ee-87d7-5df6-9a53-c2b2fd7958b3','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Забыли сжечь карту','Перед флопом, тёрном и ривером дилер должен сжечь карту. Если карта не была сожжена, действие останавливается и ошибка исправляется по процедуре рума.',11,'[]'::jsonb,'[]'::jsonb,null),
('a78a2b17-29eb-51ad-b9ab-c59f036c9eeb','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Ранний шоудаун','Если дилер объявил шоудаун раньше времени и игрок открыл карты, игрок остаётся в игре, но дальше может только уравнивать ставки.',12,'[]'::jsonb,'[]'::jsonb,null),
('0a3018d6-9aa8-5be5-84d7-ea0fb512f434','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Действие вне очереди','Если игрок намеренно действует вне очереди, дилер делает предупреждение. Если такие нарушения повторятся три раза, игрок получает отстранение на три раздачи.',13,'[]'::jsonb,'[]'::jsonb,null),
('60d52cc0-70a6-56c9-9325-f6d342817e62','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Недостаточная ставка и словесное объявление','Устное объявление обязательно исполняется фишками. Если игрок объявил рейз, но фишек не хватает, он доставляет минимальный рейз; больше заявленного ставить нельзя. Если сумма не названа, рейз считается минимальным.',14,'[]'::jsonb,'[]'::jsonb,null),
('7ab3bf0d-38a0-5887-9e2e-fdf0e2e7691e','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Олл-ин меньшего размера','Игрок может поставить олл-ин меньше полной ставки. Его фишки участвуют в основном банке и только в тех сайд-потах, в которые он может вложиться.',15,'[]'::jsonb,'[]'::jsonb,null),
('4c923879-0c3a-58b3-95d8-c942f79d5c11','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Нечётная фишка при делении банка','Если банк нельзя разделить поровну и остаётся одна нечётная фишка, её получает первый победитель по часовой стрелке от баттона.',16,'[]'::jsonb,'[]'::jsonb,null),
('d62b1ef4-2387-5b05-94dd-12cee194f77e','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Одна фишка крупного номинала','Если игрок ставит одну фишку крупнее необходимого колла и не объявляет рейз, это считается коллом. Сдача возвращается после завершения круга торгов.',17,'[]'::jsonb,'[]'::jsonb,null),
('fadfadb2-c5a4-58e1-a393-a2972a36294d','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Несколько крупных фишек без объявления','Если игрок ставит несколько фишек крупного номинала и не объявляет действие, это считается рейзом. Если игрок увеличивает ставку одной фишкой, он обязан озвучить размер ставки.',18,'[]'::jsonb,'[]'::jsonb,null),
('2cb98039-b504-5df2-81bd-30f5a9f4d698','4e83d351-53fa-5b90-a93b-b5ae42e43e72','Первая ставка одной фишкой','Если игрок делает первый бет одной фишкой и не объявляет сумму, ставка принимается на полную сумму этой фишки.',19,'[]'::jsonb,'[]'::jsonb,null) on conflict do nothing;
