begin;
create table public.learning_sections(id uuid primary key,slug text unique not null,title text not null,description text not null default '',sort_order int not null default 0,published boolean not null default true);
create table public.learning_lessons(id uuid primary key,section_id uuid not null references public.learning_sections(id),title text not null check(length(title) between 1 and 200),theory text not null check(length(theory) between 1 and 20000),video_url text,cards jsonb not null default '[]',steps jsonb not null default '[]',sort_order int not null default 0,published boolean not null default true,updated_at timestamptz not null default now());
create table public.learning_questions(id uuid primary key,section_id uuid not null references public.learning_sections(id),lesson_id uuid not null references public.learning_lessons(id),prompt text not null,options jsonb not null,correct_index int not null,cards jsonb not null default '[]',sort_order int not null default 0,check(jsonb_typeof(options)='array' and jsonb_array_length(options)>=2 and correct_index>=0 and correct_index<jsonb_array_length(options)));
create table public.learning_progress(user_id bigint not null references public.profiles(telegram_id),lesson_id uuid not null references public.learning_lessons(id),completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
create table public.learning_attempts(id uuid primary key default gen_random_uuid(),user_id bigint not null references public.profiles(telegram_id),section_id uuid not null references public.learning_sections(id),status text not null default 'open' check(status in ('open','submitted')),snapshot jsonb not null,answers jsonb,score int,total int,passed boolean,started_at timestamptz not null default now(),submitted_at timestamptz);
create unique index one_open_learning_attempt on public.learning_attempts(user_id,section_id) where status='open';
create index learning_attempt_user on public.learning_attempts(user_id,section_id);
create table public.learning_grants(id uuid primary key,user_id bigint not null references public.profiles(telegram_id),section_id uuid not null references public.learning_sections(id),granted_by bigint not null references public.profiles(telegram_id),created_at timestamptz not null default now());
create index learning_grants_user on public.learning_grants(user_id,section_id);
create function public.learning_scope(p_actor bigint,p_owner bigint,p_target bigint) returns void language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.profiles where telegram_id=p_actor and not blocked) then raise exception 'Доступ заблокирован'; end if;
 if not exists(select 1 from public.profiles where telegram_id=p_target) then raise exception 'Пользователь не найден'; end if;
 if p_actor=p_owner then return; end if;
 if p_actor<>p_target then
  if not exists(select 1 from public.memberships m join public.teams t on t.id=m.team_id where m.user_id=p_target and t.trainer_id=p_actor) then raise exception 'Нет доступа к этому ученику'; end if;
  return;
 end if;
 if not exists(select 1 from public.memberships m join public.teams t on t.id=m.team_id join public.clubs c on c.id=t.club_id where m.user_id=p_actor and m.enabled and t.enabled and c.enabled and (c.access_until is null or c.access_until>now()))
 and not exists(select 1 from public.teams t join public.clubs c on c.id=t.club_id where t.trainer_id=p_actor and t.enabled and c.enabled and (c.access_until is null or c.access_until>now())) then raise exception 'Доступ к обучению не одобрен или приостановлен'; end if;
end $$;
create function public.learning_snapshot(p_user bigint) returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('userId',p_user,
 'sections',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'description',s.description,'slug',s.slug,'lessons',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'title',l.title,'theory',l.theory,'videoUrl',l.video_url,'cards',l.cards,'steps',l.steps) order by l.sort_order,l.id) from public.learning_lessons l where l.section_id=s.id and l.published),'[]'::jsonb)) order by s.sort_order,s.id) from public.learning_sections s where s.published),'[]'::jsonb),
 'progress',coalesce((select jsonb_agg(jsonb_build_object('lessonId',lesson_id,'completedAt',completed_at)) from public.learning_progress where user_id=p_user),'[]'::jsonb),
 'attempts',coalesce((select jsonb_agg(jsonb_build_object('id',id,'sectionId',section_id,'status',status,'score',score,'total',total,'passed',passed,'startedAt',started_at,'submittedAt',submitted_at) order by started_at desc) from public.learning_attempts where user_id=p_user),'[]'::jsonb),
 'grants',coalesce((select jsonb_agg(jsonb_build_object('id',id,'sectionId',section_id,'grantedBy',granted_by,'createdAt',created_at)) from public.learning_grants where user_id=p_user),'[]'::jsonb));
$$;
create function public.learning_command(p_actor bigint,p_owner bigint,p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare target_user bigint; section_uuid uuid; lesson_uuid uuid; attempt_uuid uuid; request_uuid uuid; a public.learning_attempts; g public.learning_grants; snapshot_json jsonb; question_json jsonb; answer_json jsonb; score_value int:=0; total_value int; used_value int; allowance_value int; completed_value int; section_value public.learning_sections;
begin
 target_user:=coalesce((p_payload->>'userId')::bigint,p_actor);
 if p_action not in ('get','grant') then target_user:=p_actor; end if;
 perform public.learning_scope(p_actor,p_owner,target_user);
 if p_action='get' then return public.learning_snapshot(target_user); end if;
 perform 1 from public.profiles where telegram_id=target_user for update;
 -- Recheck after the profile lock: membership operations use the same lock.
 perform public.learning_scope(p_actor,p_owner,target_user);
 if p_action='complete' then
  lesson_uuid:=(p_payload->>'lessonId')::uuid;
  if not exists(select 1 from public.learning_lessons l join public.learning_sections s on s.id=l.section_id where l.id=lesson_uuid and l.published and s.published) then raise exception 'Урок недоступен'; end if;
 elsif p_action='start' then
  section_uuid:=(p_payload->>'sectionId')::uuid;
  select * into section_value from public.learning_sections where id=section_uuid and published;
  if not found then raise exception 'Раздел недоступен'; end if;
  if not exists(select 1 from public.learning_lessons where section_id=section_uuid and published) or exists(select 1 from public.learning_lessons l where l.section_id=section_uuid and l.published and not exists(select 1 from public.learning_progress p where p.user_id=p_actor and p.lesson_id=l.id)) then raise exception 'Сначала ознакомьтесь со всеми уроками раздела'; end if;
  if exists(select 1 from public.learning_attempts where user_id=p_actor and section_id=section_uuid and passed) then raise exception 'Тест раздела уже сдан'; end if;
  select * into a from public.learning_attempts where user_id=p_actor and section_id=section_uuid and status='open';
  if not found then
   select count(*) into used_value from public.learning_attempts where user_id=p_actor and section_id=section_uuid and status='submitted';
   select 2+count(*) into allowance_value from public.learning_grants where user_id=p_actor and section_id=section_uuid;
   if used_value>=allowance_value then raise exception 'Попытки закончились. Обратитесь к тренеру'; end if;
   select jsonb_agg(jsonb_build_object('id',q.id,'prompt',q.prompt,'options',q.options,'correctIndex',q.correct_index,'cards',q.cards) order by random()) into snapshot_json from public.learning_questions q join public.learning_lessons l on l.id=q.lesson_id where q.section_id=section_uuid and l.published;
   if snapshot_json is null then raise exception 'В разделе пока нет вопросов'; end if;
  end if;
  return public.learning_snapshot(p_actor)||jsonb_build_object('activeAttempt',jsonb_build_object('id',a.id,'sectionId',a.section_id,'questions',(select jsonb_agg(q-'correctIndex') from jsonb_array_elements(a.snapshot) q)));
 elsif p_action='submit' then
  attempt_uuid:=(p_payload->>'attemptId')::uuid;
  select * into a from public.learning_attempts where id=attempt_uuid and user_id=p_actor for update;
  if not found then raise exception 'Попытка не найдена'; end if;
  if a.status='open' then
   answer_json:=p_payload->'answers';total_value:=jsonb_array_length(a.snapshot);
   if answer_json is null or jsonb_typeof(answer_json)<>'object' then raise exception 'Ответьте на все вопросы'; end if;
   if (select count(*) from jsonb_object_keys(answer_json))<>total_value then raise exception 'Ответьте на все вопросы'; end if;
   for question_json in select value from jsonb_array_elements(a.snapshot) loop
    if jsonb_typeof(answer_json->(question_json->>'id')) is distinct from 'number' or coalesce(answer_json->>(question_json->>'id'),'')!~'^[0-9]+$' then raise exception 'Некорректный ответ'; end if;
    if (answer_json->>(question_json->>'id'))::int<0 or (answer_json->>(question_json->>'id'))::int>=jsonb_array_length(question_json->'options') then raise exception 'Некорректный вариант ответа'; end if;
    if (answer_json->>(question_json->>'id'))::int=(question_json->>'correctIndex')::int then score_value:=score_value+1; end if;
   end loop;
   update public.learning_attempts set status='submitted',answers=answer_json,score=score_value,total=total_value,passed=(score_value=total_value),submitted_at=now() where id=a.id returning * into a;
  end if;
  return public.learning_snapshot(p_actor)||jsonb_build_object('result',jsonb_build_object('id',a.id,'sectionId',a.section_id,'score',a.score,'total',a.total,'passed',a.passed));
 elsif p_action='grant' then
  if p_actor=target_user and p_actor<>p_owner then raise exception 'Нельзя выдавать попытки самому себе'; end if;
  section_uuid:=(p_payload->>'sectionId')::uuid;request_uuid:=(p_payload->>'requestId')::uuid;
  select * into g from public.learning_grants where id=request_uuid;
  if found then
   if g.user_id<>target_user or g.section_id<>section_uuid or g.granted_by<>p_actor then raise exception 'Запрос уже использован'; end if;
   return public.learning_snapshot(target_user);
  end if;
  if not exists(select 1 from public.learning_sections where id=section_uuid and published) then raise exception 'Раздел недоступен'; end if;
  if exists(select 1 from public.learning_attempts where user_id=target_user and section_id=section_uuid and passed) then raise exception 'Тест уже сдан'; end if;
  select count(*) into used_value from public.learning_attempts where user_id=target_user and section_id=section_uuid and status='submitted';
  select 2+count(*) into allowance_value from public.learning_grants where user_id=target_user and section_id=section_uuid;
  if used_value<allowance_value then raise exception 'У ученика ещё есть доступные попытки'; end if;
 elsif p_action='edit' then
  if p_actor<>p_owner then raise exception 'Редактирование доступно только владельцу'; end if;
  lesson_uuid:=(p_payload->>'lessonId')::uuid;
  update public.learning_lessons set title=trim(p_payload->>'title'),theory=trim(p_payload->>'theory'),video_url=nullif(p_payload->>'videoUrl',''),updated_at=now() where id=lesson_uuid;
  if not found then raise exception 'Урок не найден'; end if;
 else raise exception 'Неизвестное действие';
 end if;
 return public.learning_snapshot(target_user);
end $$;
alter table public.learning_sections enable row level security;
alter table public.learning_lessons enable row level security;
alter table public.learning_questions enable row level security;
alter table public.learning_progress enable row level security;
alter table public.learning_attempts enable row level security;
alter table public.learning_grants enable row level security;
revoke all on public.learning_sections,public.learning_lessons,public.learning_questions,public.learning_progress,public.learning_attempts,public.learning_grants from anon,authenticated;
grant all on public.learning_sections,public.learning_lessons,public.learning_questions,public.learning_progress,public.learning_attempts,public.learning_grants to service_role;
revoke all on function public.learning_scope(bigint,bigint,bigint),public.learning_snapshot(bigint),public.learning_command(bigint,bigint,text,jsonb) from public,anon,authenticated;
grant execute on function public.learning_scope(bigint,bigint,bigint),public.learning_snapshot(bigint),public.learning_command(bigint,bigint,text,jsonb) to service_role;



commit;
